package retry

import (
	"context"
	"errors"
	"fmt"
	"time"
)

// Sleeper waits for a duration, honoring cancellation.
type Sleeper interface {
	Sleep(ctx context.Context, duration time.Duration) error
}

// TransientError marks a failure as retryable.
type TransientError struct {
	Err        error
	RetryAfter time.Duration
}

func (e *TransientError) Error() string {
	return fmt.Sprintf("transient: %v", e.Err)
}

func (e *TransientError) Unwrap() error {
	return e.Err
}

// Config configures the retrier.
type Config struct {
	MaxAttempts int
	BaseDelay   time.Duration
}

// Dependencies holds the injected dependencies for a Retrier.
type Dependencies struct {
	Sleeper Sleeper
}

// Retrier executes an operation with retry logic.
type Retrier struct {
	config Config
	sleep  Sleeper
}

// New creates a Retrier. Returns an error if MaxAttempts < 1 or BaseDelay < 0.
// A nil Sleeper defaults to a real clock-based sleeper.
func New(configuration Config, dependencies Dependencies) (*Retrier, error) {
	if configuration.MaxAttempts < 1 {
		return nil, errors.New("retry: MaxAttempts must be >= 1")
	}
	if configuration.BaseDelay < 0 {
		return nil, errors.New("retry: BaseDelay must be >= 0")
	}
	s := dependencies.Sleeper
	if s == nil {
		s = clockSleeper{}
	}
	return &Retrier{config: configuration, sleep: s}, nil
}

// Do calls operation up to MaxAttempts times, retrying on *TransientError.
func (r *Retrier) Do(ctx context.Context, operation func(ctx context.Context) error) error {
	var lastErr error

	for attempt := 0; attempt < r.config.MaxAttempts; attempt++ {
		err := operation(ctx)
		if err == nil {
			return nil
		}

		lastErr = err

		// Check if retryable — a *TransientError must be present in the error tree.
		te, ok := errors.AsType[*TransientError](err)
		if !ok {
			return err
		}

		// Last attempt: don't sleep, just fail.
		if attempt == r.config.MaxAttempts-1 {
			return err
		}

		// Compute the delay.
		d := te.RetryAfter
		if d <= 0 {
			d = r.config.BaseDelay << attempt // BaseDelay * 2^attempt
		}

		if err := r.sleep.Sleep(ctx, d); err != nil {
			return err
		}
	}

	return lastErr
}

